/// 热键域的全部文字。按语言取实现。
pub fn hotkeys(language: AppLanguage) -> &'static dyn HotkeyStrings {
    match language {
        AppLanguage::En => &HotkeyStringsEn,
        AppLanguage::Zh => &HotkeyStringsZh,
        AppLanguage::Ru => &HotkeyStringsRu,
        AppLanguage::Ja => &HotkeyStringsJa,
        AppLanguage::Ko => &HotkeyStringsKo,
        AppLanguage::Fr => &HotkeyStringsFr,
        AppLanguage::De => &HotkeyStringsDe,
        AppLanguage::Es => &HotkeyStringsEs,
    }
}
